using System;using System.IO;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace PZ3D {static class PlaytimeDayTests {
 static Dictionary<string,object> D(object o){var j=new JavaScriptSerializer();return j.Deserialize<Dictionary<string,object>>(j.Serialize(o));}
 public static void Run(){string data=Path.Combine(LauncherTestPaths.Root,"day-"+Guid.NewGuid().ToString("N"));DateTime before=new DateTime(2026,1,1,23,59,55,DateTimeKind.Local).ToUniversalTime(),after=new DateTime(2026,1,2,0,0,5,DateTimeKind.Local).ToUniversalTime();PlaytimeTracker.Sample(data,"midnight",before,true);PlaytimeTracker.Sample(data,"midnight",after,true);var dto=D(PlaytimeTracker.SnapshotAt(data,after));if(Convert.ToInt64(dto["todaySeconds"])!=5||Convert.ToInt64(dto["totalSeconds"])!=10)throw new Exception("FAIL: playtime midnight split must preserve5seconds per local day");string waitData=Path.Combine(LauncherTestPaths.Root,"waiting-"+Guid.NewGuid().ToString("N")),nonce=Guid.NewGuid().ToString("N");LauncherNativeState.Write(Path.Combine(waitData,"playtime","launch-"+nonce+".json"),new PlaytimeRequest{nonce=nonce,created=DateTime.UtcNow.Ticks,game="fixture"});if(Convert.ToString(D(PlaytimeTracker.Snapshot(waitData))["tracking"])!="waiting")throw new Exception("FAIL: requested launch is waiting, not falsely stopped before process appears");Console.WriteLine("PASS: playtime local-midnight split and explicit waiting state");}
 public static int Main(){try{Run();return 0;}catch(Exception x){Console.WriteLine(x);return 1;}}
}}
